#!/usr/bin/env python3
"""Prueba (28-oct-2026) de la Agenda para tejedoras como app instalable: manifiesto propio, íconos, tarjeta «Instala tu agenda» y uso sin internet.
Uso: con un servidor local en el puerto 8765:  /usr/bin/python3 herramientas/pruebas/probar_agenda_app.py [carpeta_capturas]"""
import sys, json, os, urllib.request
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from agenda_util import *
T = Prueba(); CAP = sys.argv[1] if len(sys.argv) > 1 else None
RAIZ = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..')
m = json.load(open(os.path.join(RAIZ, 'manifest-agenda.webmanifest')))
T.v('el manifiesto tiene nombre, inicio en la agenda y modo app', m['name'] == 'Agenda para tejedoras' and m['start_url'].startswith('/agenda-rosina.html') and m['display'] == 'standalone' and m['scope'] == '/')
T.v('tiene íconos redondos 192 y 512 (sin maskable: en el computador salía cuadrado y verde liso) y todos existen', {i['sizes'] + i['purpose'] for i in m['icons']} == {'192x192any', '512x512any'} and all(os.path.exists(os.path.join(RAIZ, i['src'].split('?')[0].lstrip('/'))) for i in m['icons']))
T.v('los atajos del manifiesto apuntan a hojas que existen', all(('#' + sh['url'].split('#')[1]) and ('id="%s"' % sh['url'].split('#')[1]) in open(os.path.join(RAIZ, 'agenda-rosina.html')).read() for sh in m['shortcuts']))
with sync_playwright() as p:
    b = p.chromium.launch(executable_path=CHROMIUM, args=['--no-sandbox'])
    ctx = contexto(b, 390, datos={'ag-nombre': 'Bufanda lila', 'ag-ec-nombre': 'Luisa'}); pg = abrir(ctx, 'planeador-dia', 1500)
    T.v('la página enlaza su propio manifiesto, color e ícono', pg.get_attribute('link[rel=manifest]', 'href') == '/manifest-agenda.webmanifest' and pg.get_attribute('meta[name=theme-color]', 'content') == '#E01E79' and 'agenda' in pg.get_attribute('link[rel=apple-touch-icon]', 'href') and pg.get_attribute('meta[name=apple-mobile-web-app-title]', 'content') == 'Agenda para tejedoras')
    T.v('el pie mínimo ya no lleva botón de instalar (la tarjeta «Instala tu agenda como app» cubre eso) y sí logo, políticas, autoría y derechos', pg.locator('.pie-minimo [data-instalar]').count() == 0 and pg.locator('.pie-minimo .pie-logo-anim').count() == 1 and pg.locator('.pie-minimo .pie-legal a[href="/politicas.html"]').count() == 1 and 'Agenda creada por Lana Rosa Crochet' in pg.inner_text('.pie-minimo') and '© 2026' in pg.inner_text('.pie-minimo'))
    T.v('el manifiesto se puede pedir al servidor', urllib.request.urlopen(BASE + '/manifest-agenda.webmanifest').status == 200)
    T.v('la tarjeta de instalar está oculta hasta que el navegador ofrece instalar', pg.locator('#instalar-agenda').is_hidden())
    pg.evaluate("""() => { window.__prompts = 0; const e = new Event('beforeinstallprompt'); e.prompt = () => { window.__prompts++; }; e.userChoice = Promise.resolve({ outcome: 'accepted' }); window.dispatchEvent(e); }""")
    pg.wait_for_timeout(300)
    T.v('al ofrecer el navegador, aparece la tarjeta con su ícono verde', pg.locator('#instalar-agenda').is_visible() and 'icono-agenda' in pg.get_attribute('#instalar-agenda img', 'src'))
    if CAP: os.makedirs(CAP, exist_ok=True); pg.locator('#instalar-agenda').screenshot(path=os.path.join(CAP, 'instalar-390.png'))
    pg.evaluate("window.dataLayer = []"); pg.click('#ia-instalar'); pg.wait_for_timeout(300)
    T.v('«Instalar» abre el instalador del navegador, mide el clic y oculta la tarjeta', pg.evaluate('window.__prompts') == 1 and pg.locator('#instalar-agenda').is_hidden() and any(e.get('event') == 'clic_instalar_app' and e.get('app') == 'agenda' for e in pg.evaluate("window.dataLayer")))
    T.v('sin desplazamiento horizontal ni errores', pg.evaluate("document.documentElement.scrollWidth <= innerWidth + 1") and not pg.errs, pg.errs[:2])
    pg.evaluate("localStorage.removeItem('lrAgendaInstalarLuego')"); pg.reload(); pg.wait_for_timeout(1200)
    pg.evaluate("() => { const e = new Event('beforeinstallprompt'); e.prompt = () => {}; e.userChoice = Promise.resolve({}); window.dispatchEvent(e); }"); pg.wait_for_timeout(200)
    pg.click('#ia-luego'); pg.reload(); pg.wait_for_timeout(1200)
    pg.evaluate("() => { const e = new Event('beforeinstallprompt'); e.prompt = () => {}; e.userChoice = Promise.resolve({}); window.dispatchEvent(e); }"); pg.wait_for_timeout(200)
    T.v('«Ahora no» la silencia (no reaparece al volver)', pg.locator('#instalar-agenda').is_hidden())
    ctx.close()
    ctx = b.new_context(viewport={'width': 390, 'height': 800}, user_agent='Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1')
    ctx.add_init_script("localStorage.setItem('lrAgendaAvance','1');localStorage.setItem('lrConsent', JSON.stringify({v:1,a:false,t:Date.now()}));")
    ctx.route('**/googletagmanager.com/**', lambda r: r.abort()); ctx.route('**/rest/v1/rpc/**', lambda r: r.fulfill(status=200, content_type='application/json', body='[]'))
    pg = ctx.new_page(); pg.errs = []; pg.on('pageerror', lambda e: pg.errs.append(str(e))); pg.goto(BASE + '/agenda-rosina.html'); pg.wait_for_timeout(1500)
    T.v('en iPhone muestra «Cómo instalar» con la indicación de Compartir', pg.locator('#instalar-agenda').is_visible() and pg.inner_text('#ia-instalar') == 'Cómo instalar')
    pg.click('#ia-instalar'); T.v('y la indicación se despliega', pg.locator('#ia-ayuda').is_visible() and 'Añadir a pantalla de inicio' in pg.inner_text('#ia-ayuda'))
    ctx.close()
    # sin internet: el servicio guarda la agenda y sus archivos
    ctx = contexto(b, 390, datos={'ag-nombre': 'Bufanda lila'}); pg = abrir(ctx, '', 1500)
    pg.evaluate("navigator.serviceWorker.ready.then(() => true)"); pg.wait_for_timeout(800)
    pg.reload(); pg.wait_for_timeout(2500)
    T.v('el servicio está activo y controla la página', pg.evaluate("!!navigator.serviceWorker.controller"))
    claves = pg.evaluate("caches.keys()")
    T.v('guarda una copia de la agenda en su propia caché', 'lr-agenda-v2' in claves and pg.evaluate("caches.open('lr-agenda-v2').then(c => c.keys()).then(k => k.map(r => new URL(r.url).pathname))").count('/agenda-rosina.html') == 1, claves)
    guardados = pg.evaluate("caches.open('lr-agenda-v2').then(c => c.keys()).then(k => k.map(r => new URL(r.url).pathname))")
    T.v('guarda su código y estilos (js/agenda y css) y no páginas de la tienda', any(x.startswith('/js/agenda/') for x in guardados) and '/css/agenda-fichas.css' in guardados and not any(x in ('/tienda.html', '/index.html') for x in guardados), guardados[:6])
    ctx.set_offline(True); pg.reload(); pg.wait_for_timeout(2500)
    T.v('sin internet la agenda abre (no la pantalla «sin conexión»)', pg.locator('#planeador-dia').count() == 1 and 'sin conexión' not in pg.title().lower(), pg.title())
    T.v('sin internet conserva lo escrito y funciona (el planeador responde)', json.loads(pg.evaluate("localStorage.getItem('rosinaAgenda')")).get('ag-nombre') == 'Bufanda lila' and pg.locator('#pl-titulo').inner_text() != '')
    T.v('sin internet no hay errores de JavaScript de la agenda', not [e for e in pg.errs if 'agenda' in e.lower() or 'null' in e.lower()], pg.errs[:3])
    ctx.set_offline(False); ctx.close(); b.close()
T.fin()
